export function toValidUuid(id?: string | null): string {
  if (!id) return '00000000-0000-4000-8000-000000000000';
  const uuidRegex = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (uuidRegex.test(id)) return id;

  try {
    const md5 = crypto.createHash('md5').update(id).digest('hex');
    return `${md5.slice(0, 8)}-${md5.slice(8, 12)}-4${md5.slice(13, 16)}-8${md5.slice(17, 20)}-${md5.slice(20, 32)}`;
  } catch {
    const clean = id.replace(/[^a-fA-F0-9]/g, '').padEnd(32, '0').slice(0, 32);
    return `${clean.slice(0, 8)}-${clean.slice(8, 12)}-4${clean.slice(13, 16)}-8${clean.slice(17, 20)}-${clean.slice(20, 32)}`;
  }
}

